"""Stage 4 — Agent Compiler, trigger generation, grader (offline, stubbed).

Neutral synthetic specs/bundles; no fixture filename/sender/tab/SKU/bundle-id in any
assertion. Generality is shown on two different-domain bundles with no code changes.
"""

import unittest

from trace.agent import compiler, grader, trigger
from trace.agent.compiler import compile_agent

# A synthetic spec in the real Stage-3 shape (markers only; neutral content).
SPEC_MD = """# Build spec: Order intake
<!-- bundle_id: B1 | generated by the Trace Artifact Engine -->

> ⚠️ **This spec embeds real business documents** (the files in `spec_B1_files/`).

Paste this into Claude Code or Cursor to build an agent that performs this workflow. The attached files travel with this spec.

## 0. Preflight — read the attached files before writing any code

Before building anything, you MUST (the files ship next to this spec in `spec_B1_files/`):

1. Open every attached artifact:
   - `./spec_B1_files/INPUT.pdf` — input pdf. Instruction (authoritative): "reference for fields".
   - `./spec_B1_files/SHEET.xlsx` — output spreadsheet. Instruction (authoritative): "use the live tab".
4. **STOP and report — do not proceed on inference — if any artifact cannot be opened.**

## 1. Intent

UNIQUE_INTENT_MARKER: append exactly one row per task to the sheet.

## 2. Observed examples

### Example 1 — `e1` — *representative*

> some observed detail

## 3. Acceptance criteria

- The agent must use the output artifact `./spec_B1_files/SHEET.xlsx` exactly as instructed.  _(live-checked against the attached file)_
- UNIQUE_CRIT_MARKER: the appended row count equals one.  _(user-specified)_
- The confirmation is delivered in the same external thread.  _(user-specified)_
"""

BUNDLE = {"id": "B1", "name": "Order intake", "description": "Append one row per task.",
          "trigger": "A new task arrived.", "evidence_event_ids": ["e1", "e2"]}
EVENT_LOG = [{"id": "e1", "app": "Gmail", "window": "Inbox"},
             {"id": "e2", "app": "Google Sheets", "window": "Ledger"}]


class CompilerTest(unittest.TestCase):
    def setUp(self):
        self.c = compile_agent(BUNDLE, SPEC_MD, EVENT_LOG)

    def test_test_envelope_has_no_mcp(self):
        d = self.c["test"]["dict"]
        self.assertEqual(d["name"], "Order intake (test)")
        self.assertEqual([t["type"] for t in d["tools"]], [compiler.config.AGENT_TOOLSET_TYPE])
        self.assertNotIn("mcp_servers", d)

    def test_spec_substantive_content_verbatim_in_system(self):
        sysm = self.c["test"]["dict"]["system"]
        self.assertIn("UNIQUE_INTENT_MARKER: append exactly one row per task to the sheet.", sysm)
        self.assertIn("UNIQUE_CRIT_MARKER: the appended row count equals one.", sysm)
        self.assertIn("STOP and report", sysm)

    def test_paths_rewritten_to_mount_and_wrapper_dropped(self):
        sysm = self.c["test"]["dict"]["system"]
        self.assertIn(compiler.config.MOUNT_PATH + "/INPUT.pdf", sysm)
        self.assertIn(compiler.config.MOUNT_PATH + "/SHEET.xlsx", sysm)
        self.assertNotIn("spec_B1_files/", sysm)                 # no session-relative path
        self.assertNotIn("Paste this into Claude Code", sysm)    # wrapper line dropped
        self.assertIn("before processing any task", sysm)        # preflight reworded
        self.assertNotIn("before writing any code", sysm)

    def test_framing_test_states_no_connections(self):
        self.assertIn("NO external connections", self.c["test"]["dict"]["system"])

    def test_framing_instructs_writing_outputs_to_a_new_path(self):
        # mounted files are read-only; the agent must write outputs elsewhere
        for mode in ("test", "live"):
            sysm = self.c[mode]["dict"]["system"]
            self.assertIn(compiler.config.OUTPUTS_PATH, sysm)
            self.assertIn("READ-ONLY", sysm)

    def test_live_envelope_connectors_and_approval_policy(self):
        d = self.c["live"]["dict"]
        mcp = [t for t in d["tools"] if t["type"] == "mcp_toolset"]
        names = sorted(t["mcp_server_name"] for t in mcp)
        self.assertEqual(names, ["gmail", "google_drive"])       # from the app table
        for t in mcp:
            self.assertEqual(t["default_config"]["permission_policy"]["type"],
                             compiler.config.APPROVAL_PERMISSION_POLICY)
        self.assertEqual({s["name"] for s in d["mcp_servers"]}, {"gmail", "google_drive"})

    def test_yaml_valid_and_tab_free(self):
        for mode in ("test", "live"):
            text = self.c[mode]["yaml"]
            self.assertNotIn("\t", text)
            parsed = compiler.validate_yaml(text)
            self.assertEqual(parsed["model"], compiler.config.DEFAULT_MODEL)
            self.assertIn("system", parsed)

    def test_unmapped_apps_surfaced_as_comment(self):
        bundle = {**BUNDLE, "evidence_event_ids": ["e1", "e2", "e3"]}
        ev = EVENT_LOG + [{"id": "e3", "app": "MysteryApp", "window": "x"}]
        c = compile_agent(bundle, SPEC_MD, ev)
        self.assertIn("MysteryApp", c["live"]["unmapped_apps"])
        self.assertIn("# unmapped observed apps", c["live"]["yaml"])

    def test_model_is_config_not_hardcoded(self):
        c = compile_agent(BUNDLE, SPEC_MD, EVENT_LOG, model="claude-haiku-4-5")
        self.assertEqual(c["test"]["dict"]["model"], "claude-haiku-4-5")


class GeneralityTest(unittest.TestCase):
    def test_second_domain_compiles_valid(self):
        # different apps (recruiter-ish): ATS + LinkedIn (both unmapped) + Calendar
        bundle = {"id": "R1", "name": "Resume screen", "description": "Screen resumes.",
                  "trigger": "A new applicant appeared.", "evidence_event_ids": ["x1", "x2", "x3"]}
        ev = [{"id": "x1", "app": "ATS", "window": "App"},
              {"id": "x2", "app": "LinkedIn", "window": "Search"},
              {"id": "x3", "app": "Calendar", "window": "New"}]
        c = compile_agent(bundle, SPEC_MD.replace("B1", "R1"), ev)
        # calendar maps; ats/linkedin do not -> surfaced as unmapped, never guessed
        live = c["live"]["dict"]
        names = sorted(t["mcp_server_name"] for t in live["tools"] if t["type"] == "mcp_toolset")
        self.assertEqual(names, ["google_calendar"])
        self.assertEqual(sorted(c["live"]["unmapped_apps"]), ["ATS", "LinkedIn"])
        compiler.validate_yaml(c["test"]["yaml"])
        compiler.validate_yaml(c["live"]["yaml"])


class TriggerTest(unittest.TestCase):
    def test_trigger_from_bundle_and_inputs(self):
        env = {"artifacts": [
            {"role": "input", "uploaded": True, "file_ref": "/s/PO.pdf", "user_instruction": "the PO"},
            {"role": "output", "uploaded": True, "file_ref": "/s/SHEET.xlsx", "user_instruction": "the sheet"}]}
        trigs = trigger.generate_triggers(BUNDLE, env, max_sessions=3)
        self.assertEqual(len(trigs), 1)                          # one input -> one session
        self.assertIn("A new task arrived.", trigs[0]["message"])
        self.assertIn(compiler.config.MOUNT_PATH + "/PO.pdf", trigs[0]["message"])
        self.assertEqual(trigs[0]["input_files"], ["PO.pdf"])

    def test_multiple_inputs_capped(self):
        env = {"artifacts": [{"role": "input", "uploaded": True, "file_ref": f"/s/in{i}.pdf",
                              "user_instruction": ""} for i in range(5)]}
        self.assertEqual(len(trigger.generate_triggers(BUNDLE, env, max_sessions=2)), 2)

    def test_no_inputs_still_one_trigger(self):
        self.assertEqual(len(trigger.generate_triggers(BUNDLE, {"artifacts": []})), 1)


GROUNDING = {"bundle_id": "B1", "instructions": [
    {"key": "step_1_open", "text": "Open the item.", "source": {"type": "events", "ids": ["e1"]}},
    {"key": "req_1_enter", "text": "The order values are entered into the destination.", "source": {"type": "discovery"}},
    {"key": "req_2_reply", "text": "A confirmation reply is produced.", "source": {"type": "discovery"}},
    {"key": "req_3_format", "text": "The rows match the destination file's column format.", "source": {"type": "discovery"}},
]}


def _grade_judge(per):
    """A stub judge_fn(acceptance_criteria, transcript) -> JSON text."""
    import json
    return lambda criteria, transcript: json.dumps(per)


class GraderTest(unittest.TestCase):
    def test_criteria_from_grounding_requirements_only(self):
        crit = grader.criteria_from_grounding(GROUNDING)
        self.assertEqual(len(crit), 3)                      # the three req_* entries
        self.assertNotIn("Open the item.", crit)            # steps excluded by default
        self.assertEqual(len(grader.criteria_from_grounding(GROUNDING, keys=("req_", "step_"))), 4)

    def test_grade_pass_and_not_testable(self):
        crit = grader.criteria_from_grounding(GROUNDING)
        per = {"per_criterion": [
            {"criterion": crit[0], "verdict": "pass", "reason": "ok"},
            {"criterion": crit[1], "verdict": "pass", "reason": "ok"},
            {"criterion": crit[2], "verdict": "not_testable_here", "reason": "needs real file"}],
            "overall": "pass", "notes": ""}
        rep = grader.grade(crit, "transcript text", judge_fn=_grade_judge(per))
        self.assertEqual(rep["overall"], "pass")            # not_testable_here never fails
        self.assertEqual(sum(1 for r in rep["per_criterion"] if r["verdict"] == "not_testable_here"), 1)

    def test_failing_criterion_forces_overall_fail(self):
        # the model claims overall pass, but a per-criterion fail must override it
        per = {"per_criterion": [{"criterion": "x", "verdict": "fail", "reason": "contradicted"}],
               "overall": "pass", "notes": ""}
        rep = grader.grade(["x"], "t", judge_fn=_grade_judge(per))
        self.assertEqual(rep["overall"], "fail")            # safety-net; gate can fail

    def test_inconclusive_is_non_blocking(self):
        per = {"per_criterion": [{"criterion": "x", "verdict": "inconclusive", "reason": "no evidence"}],
               "overall": "fail", "notes": ""}
        rep = grader.grade(["x"], "t", judge_fn=_grade_judge(per))
        self.assertEqual(rep["overall"], "pass")            # inconclusive doesn't fail overall

    def test_parse_grade_handles_fenced_and_unparseable(self):
        import json
        per = {"per_criterion": [{"criterion": "x", "verdict": "pass", "reason": "ok"}],
               "overall": "pass", "notes": ""}
        fenced = lambda c, t: "```json\n" + json.dumps(per) + "\n```"
        self.assertEqual(grader.grade(["x"], "t", judge_fn=fenced)["overall"], "pass")
        bad = grader.grade(["x"], "t", judge_fn=lambda c, t: "totally not json")
        self.assertEqual(bad["overall"], "fail")            # fail-safe
        self.assertIn("unparseable", bad["notes"])


if __name__ == "__main__":
    unittest.main()
